DROP TABLE IF EXISTS {{catalog}}.{{schema}}.business_license_certified;
CREATE TABLE {{catalog}}.{{schema}}.business_license_certified (id STRING NOT NULL, license_number BIGINT NOT NULL, legal_name STRING NOT NULL, application_type STRING NOT NULL, license_status STRING NOT NULL, license_start_date TIMESTAMP, expiration_date TIMESTAMP, latitude DOUBLE, longitude DOUBLE, _ingested_at TIMESTAMP NOT NULL, CONSTRAINT valid_application CHECK (application_type IN ('ISSUE','RENEW','C_LOC','C_CAPA','C_EXPA','C_SBA')), CONSTRAINT valid_status CHECK (license_status IN ('AAI','AAC','REV','REA')), CONSTRAINT valid_dates CHECK (expiration_date IS NULL OR license_start_date IS NULL OR expiration_date >= license_start_date), CONSTRAINT valid_lat CHECK (latitude IS NULL OR latitude BETWEEN -90 AND 90), CONSTRAINT valid_lon CHECK (longitude IS NULL OR longitude BETWEEN -180 AND 180)) USING DELTA;
INSERT INTO {{catalog}}.{{schema}}.business_license_certified SELECT id,license_number,legal_name,application_type,license_status,license_start_date,expiration_date,latitude,longitude,_ingested_at FROM {{catalog}}.{{schema}}.business_license_validated;
